 500→// setupAgentHooks sets up hooks for a given agent.
 501→// Returns the number of hooks installed (0 if already installed).
 502→func setupAgentHooks(ag agent.Agent, localDev, forceHooks bool) (int, error) { //nolint:unparam // return value used by setupAgentHooksNonInteractive
 503→	hookAgent, ok := ag.(agent.HookSupport)
 504→	if !ok {
 505→		return 0, fmt.Errorf("agent %s does not support hooks", ag.Name())
 506→	}
 507→
 508→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
 509→	if err != nil {
 510→		return 0, fmt.Errorf("failed to install %s hooks: %w", ag.Name(), err)
 511→	}
 512→
 513→	return count, nil
 514→}
